using System.Collections.Generic;
using System.IO;
using Buried.Editor;
using Buried.Walk;
using NUnit.Framework;
using UnityEditor;
using UnityEngine;

namespace Buried.Tests
{
    /// <summary>
    /// The walk test (spec 07): the recorded asset, the placement of the model on its manifest, the colliders, the bounds
    /// property, the walking step maths and the plaque cone. The model is generated by `Buried.Editor.Setup.Run`, so these
    /// tests need the glb in the project and fail if it is missing.
    /// </summary>
    public class WalkTests
    {
        private const float MarkerToleranceM = 0.02f;

        private static WalkManifest Manifest()
        {
            return WalkManifest.Parse(File.ReadAllText(Path.Combine(TestPaths.UnityRoot, WalkSetup.ManifestPath)));
        }

        private static GameObject Instantiate(string path)
        {
            var asset = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            Assert.IsNotNull(asset, path + " is not in the project (run Buried.Editor.Setup.Run)");
            return Object.Instantiate(asset);
        }

        // ---- The recorded asset (requirement 1) ----

        [Test]
        public void TheWalkAssetRecordsTheModelAndTheManifest()
        {
            var asset = AssetDatabase.LoadAssetAtPath<WalkAsset>(WalkSetup.AssetPath);
            Assert.IsNotNull(asset, WalkSetup.AssetPath + " is missing: run `tools/unity.sh exec Buried.Editor.Setup.Run`");
            Assert.IsNotNull(asset.model, "the walk asset has no model");
            Assert.IsNotNull(asset.manifest, "the walk asset has no manifest");
            Assert.AreEqual(Manifest().plaques.Count, WalkManifest.Parse(asset.manifest.text).plaques.Count);
        }

        [Test]
        public void TheModelHasANodeForEveryManifestEntry()
        {
            GameObject model = Instantiate(WalkSetup.PrefabPath);
            try
            {
                Dictionary<string, Transform> nodes = WalkPlacement.Index(model.transform);
                WalkManifest manifest = Manifest();
                foreach (WalkManifest.Named r in manifest.refs) Assert.IsTrue(nodes.ContainsKey(r.name), r.name);
                foreach (WalkManifest.Named l in manifest.lamps) Assert.IsTrue(nodes.ContainsKey(l.name), l.name);
                foreach (WalkManifest.Plaque p in manifest.plaques)
                {
                    Assert.IsTrue(nodes.ContainsKey("plaque_" + p.slug), "plaque_" + p.slug);
                    Assert.IsTrue(nodes.ContainsKey(WalkPlacement.PlaquePrefix + p.slug), WalkPlacement.PlaquePrefix + p.slug);
                }
                Assert.IsTrue(nodes.ContainsKey(WalkPlacement.SpawnName));
                Assert.IsTrue(nodes.ContainsKey(WalkPlacement.HandLanternName));
            }
            finally
            {
                Object.DestroyImmediate(model);
            }
        }

        // ---- Placement (requirement 2) ----

        [Test]
        public void PlacingTheImportedModelPutsEveryMarkerWithinTwoCentimetresOfTheManifest()
        {
            GameObject model = Instantiate(WalkSetup.GlbPath);
            try
            {
                WalkManifest manifest = Manifest();
                WalkPlacement.Place(model, manifest);
                string worst;
                float error = WalkPlacement.MaxMarkerError(model, manifest, out worst);
                Assert.LessOrEqual(error, MarkerToleranceM, "worst marker: " + worst);

                // Placing again changes nothing.
                WalkPlacement.Place(model, manifest);
                Assert.LessOrEqual(WalkPlacement.MaxMarkerError(model, manifest, out worst), MarkerToleranceM, "after a second placement, worst marker: " + worst);
            }
            finally
            {
                Object.DestroyImmediate(model);
            }
        }

        [Test]
        public void TheRecordedModelIsAlreadyPlaced()
        {
            GameObject model = Instantiate(WalkSetup.PrefabPath);
            try
            {
                string worst;
                Assert.LessOrEqual(WalkPlacement.MaxMarkerError(model, Manifest(), out worst), MarkerToleranceM, "worst marker: " + worst);
            }
            finally
            {
                Object.DestroyImmediate(model);
            }
        }

        [Test]
        public void SurfacesGetMeshCollidersPostsGetCapsulesAndSignsAndRailsGetNone()
        {
            GameObject model = Instantiate(WalkSetup.PrefabPath);
            try
            {
                int surfaces = 0, posts = 0;
                foreach (Transform node in model.GetComponentsInChildren<Transform>(true))
                {
                    string n = node.name;
                    if (n.StartsWith("ground_") || n.StartsWith("bld_") || n.StartsWith("fence_"))
                    {
                        foreach (MeshFilter f in node.GetComponentsInChildren<MeshFilter>(true))
                        {
                            Assert.IsNotNull(f.GetComponent<MeshCollider>(), n + " has a mesh without a mesh collider");
                            surfaces++;
                        }
                    }
                    else if (n.StartsWith("prop_lamp_") || n.StartsWith("prop_pole_") || n.StartsWith("prop_hydrant_") || n.StartsWith("plaque_"))
                    {
                        Assert.IsNotNull(node.GetComponent<CapsuleCollider>(), n + " has no capsule collider");
                        posts++;
                    }
                    else if (n.StartsWith("sign_") || n.StartsWith("rail_") || n == WalkPlacement.HandLanternName || n.StartsWith("marker_"))
                    {
                        Assert.AreEqual(0, node.GetComponentsInChildren<Collider>(true).Length, n + " must have no collider");
                    }
                }
                Assert.Greater(surfaces, 0);
                Assert.Greater(posts, 0);
            }
            finally
            {
                Object.DestroyImmediate(model);
            }
        }

        [Test]
        public void TheSpawnPointIsInsideTheWalkBoundsAndSoIsEveryLampPost()
        {
            WalkManifest manifest = Manifest();
            Assert.IsTrue(WalkMath.Inside(manifest.walkBounds, new Vector2(manifest.spawnPos.x, manifest.spawnPos.z)));
        }

        // ---- The rigid fit ----

        [Test]
        public void TheRigidFitRecoversAnyTurnTranslationAndMirror()
        {
            PropertyRunner.Run("rigid fit", 4901, 500, (rng, i) =>
            {
                var truth = new WalkMath.Rigid
                {
                    Mirror = rng.Next(2) == 0,
                    YawDeg = (float)PropertyRunner.Uniform(rng, 0, 360),
                    Translation = new Vector3((float)PropertyRunner.Uniform(rng, -300, 300), (float)PropertyRunner.Uniform(rng, -5, 5), (float)PropertyRunner.Uniform(rng, -300, 300)),
                };
                var source = new List<Vector3>();
                for (int k = 0; k < 3; k++)
                {
                    source.Add(new Vector3((float)PropertyRunner.Uniform(rng, -80, 80), 0f, (float)PropertyRunner.Uniform(rng, -80, 80)));
                }
                // Three points on one line fit a turn about that line in no way; skip those.
                Vector3 a = source[1] - source[0], b = source[2] - source[0];
                if (Mathf.Abs(a.x * b.z - a.z * b.x) < 200f) return;

                var target = new List<Vector3>();
                foreach (Vector3 s in source) target.Add(truth.Apply(s));
                float error;
                WalkMath.Rigid fit = WalkMath.FitRigid(source, target, out error);
                Assert.Less(error, 0.01f);
                for (int k = 0; k < 3; k++) Assert.Less((fit.Apply(source[k]) - target[k]).magnitude, 0.01f);
            });
        }

        // ---- Bounds (requirement 3.3) ----

        private static Vector2 RandomInside(Vector2[] polygon, System.Random rng)
        {
            float minX = float.MaxValue, minY = float.MaxValue, maxX = float.MinValue, maxY = float.MinValue;
            foreach (Vector2 p in polygon)
            {
                minX = Mathf.Min(minX, p.x);
                maxX = Mathf.Max(maxX, p.x);
                minY = Mathf.Min(minY, p.y);
                maxY = Mathf.Max(maxY, p.y);
            }
            for (int attempt = 0; attempt < 1000; attempt++)
            {
                var p = new Vector2((float)PropertyRunner.Uniform(rng, minX, maxX), (float)PropertyRunner.Uniform(rng, minY, maxY));
                if (WalkMath.Inside(polygon, p)) return p;
            }
            Assert.Fail("no point inside the polygon was found");
            return Vector2.zero;
        }

        [Test]
        public void FromAnyStartInsideAnyMoveEndsInside()
        {
            Vector2[] bounds = Manifest().walkBounds;
            PropertyRunner.Run("bounds", 4902, 2000, (rng, i) =>
            {
                Vector2 position = RandomInside(bounds, rng);
                for (int step = 0; step < 12; step++)
                {
                    float length = (float)PropertyRunner.Uniform(rng, 0, step % 4 == 3 ? 80 : 6);
                    float angle = (float)PropertyRunner.Uniform(rng, 0, Mathf.PI * 2);
                    Vector2 target = position + new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * length;
                    position = WalkMath.KeepInside(bounds, position, target);
                    Assert.IsTrue(WalkMath.Inside(bounds, position), "step " + step + " ended at " + position);
                }
            });
        }

        [Test]
        public void PushingAgainstAnEdgeSlidesAlongItAndNeverSticks()
        {
            Vector2[] bounds = Manifest().walkBounds;
            Vector2 a = bounds[0], b = bounds[1];
            Vector2 along = (b - a).normalized;
            Vector2 middle = (a + b) * 0.5f;
            Vector2 inward = new Vector2(-along.y, along.x);
            if (!WalkMath.Inside(bounds, middle + inward * 0.5f)) inward = -inward;

            Vector2 start = middle + inward * 0.5f;
            Vector2 end = WalkMath.KeepInside(bounds, start, start - inward * 2f + along * 3f);
            Assert.IsTrue(WalkMath.Inside(bounds, end));
            Assert.Greater(Vector2.Dot(end - start, along), 2.5f, "the visitor stuck at the edge instead of sliding along it");
        }

        // ---- Walking (requirement 3.1, 3.2) ----

        [Test]
        public void WalkingAndRunningSpeedsAreTheBriefsAndADiagonalIsNoFaster()
        {
            Vector2 north = WalkMath.Velocity(new Vector2(0, 1), 0f, false);
            Assert.AreEqual(2.4f, north.magnitude, 1e-4f);
            Assert.AreEqual(0f, north.x, 1e-4f);
            Assert.AreEqual(2.4f, north.y, 1e-4f);

            Vector2 east = WalkMath.Velocity(new Vector2(0, 1), 90f, false);
            Assert.AreEqual(2.4f, east.x, 1e-4f);
            Assert.AreEqual(0f, east.y, 1e-4f);

            Assert.AreEqual(4.6f, WalkMath.Velocity(new Vector2(0, 1), 33f, true).magnitude, 1e-4f);
            Assert.AreEqual(2.4f, WalkMath.Velocity(new Vector2(1, 1), 33f, false).magnitude, 1e-4f);
            Assert.AreEqual(0f, WalkMath.Velocity(Vector2.zero, 33f, true).magnitude, 1e-6f);

            // D is to the right: facing north, it moves east. A is to the left.
            Vector2 right = WalkMath.Velocity(new Vector2(1, 0), 0f, false);
            Assert.AreEqual(2.4f, right.x, 1e-4f);
            Vector2 back = WalkMath.Velocity(new Vector2(0, -1), 0f, false);
            Assert.AreEqual(-2.4f, back.y, 1e-4f);
        }

        [Test]
        public void PitchStaysWithinEightyDegreesAndYawWrapsToACircle()
        {
            Assert.AreEqual(80f, WalkMath.ClampPitch(120f));
            Assert.AreEqual(-80f, WalkMath.ClampPitch(-120f));
            Assert.AreEqual(12f, WalkMath.ClampPitch(12f));
            PropertyRunner.Run("yaw", 4903, 500, (rng, i) =>
            {
                float yaw = WalkMath.WrapYaw((float)PropertyRunner.Uniform(rng, -2000, 2000));
                Assert.GreaterOrEqual(yaw, 0f);
                Assert.Less(yaw, 360f);
            });
        }

        [Test]
        public void TheVisitorsNumbersAreTheBriefs()
        {
            Assert.AreEqual(0.3f, WalkSettings.CapsuleRadiusM);
            Assert.AreEqual(1.62f, WalkSettings.EyeHeightM);
            Assert.AreEqual(2.4f, WalkSettings.WalkSpeedMs);
            Assert.AreEqual(4.6f, WalkSettings.RunSpeedMs);
            Assert.AreEqual(0.3f, WalkSettings.StepHeightM);
            Assert.AreEqual(3.2f, WalkSettings.PlaqueRangeM);
            Assert.AreEqual(25f, WalkSettings.PlaqueConeDeg);
        }

        // ---- Plaques (requirement 5.1) ----

        private static List<WalkMath.PlaqueTarget> Plaques()
        {
            return new List<WalkMath.PlaqueTarget>
            {
                new WalkMath.PlaqueTarget { Slug = "near", Position = new Vector3(0f, 1f, 3f) },
                new WalkMath.PlaqueTarget { Slug = "side", Position = new Vector3(3f, 1f, 0f) },
            };
        }

        [Test]
        public void ThePlaqueConeNeedsRangeAndAim()
        {
            Vector3 eye = new Vector3(0f, 1.62f, 0f);
            Assert.AreEqual("near", WalkMath.NearestPlaque(eye, Vector3.forward, Plaques(), 3.2f, 25f));
            Assert.AreEqual("side", WalkMath.NearestPlaque(eye, Vector3.right, Plaques(), 3.2f, 25f));
            Assert.IsNull(WalkMath.NearestPlaque(eye, Vector3.back, Plaques(), 3.2f, 25f), "looking away");
            Assert.IsNull(WalkMath.NearestPlaque(eye + Vector3.back * 2f, Vector3.forward, Plaques(), 3.2f, 25f), "5 m is out of reach");
            Vector3 aim24 = Quaternion.Euler(0f, 24f, 0f) * Vector3.forward;
            Vector3 aim30 = Quaternion.Euler(0f, 30f, 0f) * Vector3.forward;
            Assert.AreEqual("near", WalkMath.NearestPlaque(new Vector3(0f, 1f, 0f), aim24, Plaques(), 3.2f, 25f));
            Assert.IsNull(WalkMath.NearestPlaque(new Vector3(0f, 1f, 0f), aim30, Plaques(), 3.2f, 25f));
            Assert.IsNull(WalkMath.NearestPlaque(eye, Vector3.zero, Plaques(), 3.2f, 25f));
        }

        [Test]
        public void OfTwoPlaquesInViewTheOneNearerTheMiddleWins()
        {
            var both = new List<WalkMath.PlaqueTarget>
            {
                new WalkMath.PlaqueTarget { Slug = "left", Position = new Vector3(-0.8f, 1f, 3f) },
                new WalkMath.PlaqueTarget { Slug = "ahead", Position = new Vector3(0.1f, 1f, 3f) },
            };
            Assert.AreEqual("ahead", WalkMath.NearestPlaque(new Vector3(0f, 1f, 0f), Vector3.forward, both, 3.2f, 25f));
        }

        [Test]
        public void EveryManifestPlaqueCanBeReadFromInFrontOfIt()
        {
            WalkManifest manifest = Manifest();
            var targets = new List<WalkMath.PlaqueTarget>();
            foreach (WalkManifest.Plaque p in manifest.plaques) targets.Add(new WalkMath.PlaqueTarget { Slug = p.slug, Position = p.pos });
            foreach (WalkManifest.Plaque p in manifest.plaques)
            {
                Vector3 eye = p.pos + p.facing.normalized * 1.5f;
                eye.y = WalkSettings.EyeHeightM;
                Vector3 look = p.pos - eye;
                Assert.AreEqual(p.slug, WalkMath.NearestPlaque(eye, look, targets, WalkSettings.PlaqueRangeM, WalkSettings.PlaqueConeDeg));
            }
        }
    }
}
